{"content": "/**
 * script-paths.ts — the `test` scripts in package.json, and the paths they name.
 *
 * Two contract tests ask about those scripts: `test-script.test.ts` (every path a
 * script names exists, because `bun test <path that does not exist>` exits 0) and
 * `test-builds-first.test.ts` (each script builds `dist/` before it reads it). Both
 * need the same answer to "which paths does this command run", and a second copy of
 * that parse is the thing that decays: the later reader fixes one of them and CI
 * keeps reading the other, with nothing saying so.
 *
 * `src/entrypoints/machinery/testing/harness.ts` exists for the same reason, one
 * level down.
 */
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";

/** Every script in package.json, by name. */
export function scripts(): Record<string, string> {
  return (JSON.parse(readFileSync("package.json", "utf8")) as { scripts: Record<string, string> }).scripts;
}

/** The arguments to `bun test`, which are paths. The command itself is not. */
export function pathsOf(command: string): string[] {
  return command
    .split(/\s+/)
    .slice(2)
    .filter((word) => word.startsWith("./") || word.startsWith("src/") || word.startsWith("tests/"));
}

/**
 * Every `.ts` a path named by a script covers, at any depth.
 *
 * `.ts` only: the code that reads a file is TypeScript in this repository, and a
 * directory here holds data (`tests/fixtures/`) and YAML beside it.
 */
export function typescriptFilesUnder(path: string): string[] {
  if (!existsSync(path)) return [];
  if (!statSync(path).isDirectory()) return path.endsWith(".ts") ? [path] : [];
  return readdirSync(path, { recursive: true })
    .map(String)
    .map((name) => join(path, name).replaceAll("\\", "/"))
    .filter((file) => file.endsWith(".ts") && statSync(file).isFile());
}
